const sid = '6f1c2b1e-2d3a-4b5c-8d9e-0f1a2b3c4d5e';
for (const [name, agent] of [['triage', triage], ['orderAgent', orderAgent], ['refundAgent', refundAgent]] as const) {
  try {
    await (agent as any).chat({ sessionId: sid }).send('What is its status?');
    console.log(name, 'resume: accepted');
  } catch (e: any) {
    console.log(name, 'resume error:', e?.message ?? e);
  }
}
EOF
cd /tmp/probe && GEMINI_API_KEY=fake timeout 60 node_modules/.bin/tsx /tmp/probe/probe.ts 2>&1 | head -40
